// 어디서나 같은 이름으로
const ENV = import.meta.env.MODE;          // 'development' | 'staging' | 'production'

if (ENV !== 'production') {
  document.body.dataset.env = ENV;          // CSS 로 배너 표시
  console.warn(`⚠ ${ENV} 환경입니다`);
}

// 로그, 오류에도 환경과 버전을 붙인다 (6장)
Sentry.init({ environment: ENV, release: import.meta.env.VITE_COMMIT_SHA });

// 나쁨. 나중에 검색, 집계가 안 된다
console.log(`user ${id} failed to pay ${amount} because ${e.message}`);

// 좋음. 필드로 남긴다
logger.error({
  event: 'payment.failed',
  requestId, userId: id, amount,
  reason: e.code,
  err: { name: e.name, message: e.message },
});

// 이러면 payment.failed 를 reason 별로 세기 같은 질문에 답할 수 있다

Sentry.init({
  dsn, environment: ENV,
  release: COMMIT_SHA,             // 어느 배포에서 났나 (2장)
  tracesSampleRate: 0.1,           // 추적은 표본만
  ignoreErrors: [
    'ResizeObserver loop limit exceeded',   // 알려진 소음
    /^Non-Error promise rejection/,
  ],
  beforeSend(event) {
    if (isBot(navigator.userAgent)) return null;    // 봇 제외
    return scrubPII(event);                          // 개인정보 제거
  },
});

import { onLCP, onCLS, onINP } from 'web-vitals';

const send = (m) => navigator.sendBeacon('/rum', JSON.stringify({
  name: m.name, value: m.value,
  path: location.pathname,
  conn: navigator.connection?.effectiveType,   // 4g/3g 별로 나눠 본다
  release: COMMIT_SHA,
}));
onLCP(send); onCLS(send); onINP(send);

// 판단은 75분위로. 상위 25% 가 나쁜 쪽 (렌더링 7장)
